def topo_order(n, edges):
    indeg = [0] * n
    g = [[0] * n for _ in range(n)]
    for u, v in edges:
        g[u][v] = 1
        indeg[v] += 1
    q = []
    for i in range(n):
        if indeg[i] == 0:
            q.append(i)
    head = 0
    out = []
    while head < len(q):
        u = q[head]
        head += 1
        out.append(str(u))
        for v in range(n):
            if g[u][v] == 1:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
    return ' '.join(out)

